#!/usr/bin/env node
/** Generate _tr-{N}-{slug}.mjs and _patch-siman-{N}-editorial.mjs for simanim 129–130 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const WORK = path.dirname(fileURLToPath(import.meta.url));

const DATA = {
  129: {
    'baer-heitev': {
      '6#_': `Permitted. Shach wrote in the name of Rashba that even open wine is permitted; and it implies that even if the Jew goes to stay and the gentile knows his intent to sail far, even so it is permitted because he thinks that when he remembers his wine he will immediately repent and come. Taz wrote: even though above seif 1, when informing that he sails, it is forbidden — one can say here it is different, for regarding hearing the sound of a shofar or prayer in the synagogue he does not go on his own but suddenly by chance, and therefore his wine is forgotten; the gentile sees this and trembles lest he remember the wine. But when informing that he sails, he certainly consoles himself before leaving and the gentile thinks he intentionally left the wine with him and trusts him — therefore he does not tremble — end of his words.`,
      '9#א': `And an opening. It can be seen by all; if not, this side and that side are forbidden — Shach; and above siman 128 seif 3.`,
      '15#_': `Permitted. He has no time to libate (he is busy at his work) — Rosh and Tur.`,
      '17#ב': `With a cork. Taz wrote what Rama said, that if sealed with a cork — meaning of wood — it is permitted; this is not so, for the permit applies only with clay. (And Nekudot HaKesef challenged him and wrote that specifically in an inn one returns a wood cork, but here if he had touched it he would not have bothered to return and seal it, since he left it to be lost; Bach likewise.)`,
      '20#ב': `As explained. Shach explained that there it was explained that we do not concern ourselves lest he touched to libate except when he touched for his benefit; even if he removed the spigot intentionally it is permitted since he had no intent to libate — it is gentile touch through something else without intent; we do not concern ourselves lest she touched by hand the wine in the barrel or touched what came out by what she drew, for then what is inside is also forbidden through the stream, since she need not do so. And above what Rama wrote that the maidservant is not trusted — that deals when she cannot take unless she touches by hand, such as when there is no spigot on the barrel and she must draw from the barrel by hand; but where there is a spigot, even if it is known she took the wine from the cellar, for us nowadays it is permitted in a place of loss; but Taz forbids if it is certain she drew the wine through the spigot, even for us. (And I already wrote the reason for their dispute in siman 124, and Nekudot HaKesef disagrees — see there.)`,
    },
    'beer-hagolah': {
      '4#_': `Tur; and likewise Rashba — from what we say in the Gemara there that we are not concerned lest he took it to heart, etc., we learn that if we know he took it to heart we are concerned, since he has a connection there in the shop.`,
      '7#_': `Tur; and likewise Rashba in the name of Raavad; and he wrote that the Mechaber used the phrase "he went to Kapandaria" to say they did not know he had gone to the bathhouse.`,
      '15#_': `There, in the name of Raavad; and as the Ramban ruled, the Rosh and Ran brought it there, and to this they agreed.`,
    },
    'beur-hagra': {
      '1#א': `(Extract) L'chatchila, etc. For the mishnah teaches "one who leaves" — and as he inferred at the beginning of Chullin (and Shach above siman 118 seif kaf-bet) (end).`,
      '1#ב': `Even if he stayed, etc. As our version in the Gemara "even… more than a mil"; and in the Yerushalmi they brought the variant there in the passage "and all barrels…" — Yerushalmi: an incident on a ship, etc. (Extract) Even if he stayed, etc. — Gemara there and Yerushalmi and Tosefta as stated (end).`,
      '1#ח': `And some say, etc. As stated in the Gemara "since, after all… because of connection it is permitted"; and Tosafot there in the passage "what is the reason, etc."; and likewise Raah in that passage.`,
      '3#א': `That which is permitted, etc. Rosh there seif 12 and Raavad, etc.; and he also said in the Yerushalmi, etc.; and likewise in Tosafot HaRosh 27. (Extract) That which is permitted, etc. — Tosafot there in the passage "what he left, etc." — according to Rashi (end).`,
      '3#ב': `(Extract) Without a cork. Meaning: with a cork, even in the case of one who passes through, it is permitted. Rosh and Ran in the name of Ramban, unlike Raavad who wrote specifically regarding fully sealed barrels — Ran there; and proof — Rosh and Ran wrote from the fact that we include all of them together in "bay" implies it deals with one category, and "passing with a cork" means open ones.`,
      '3#ג': `But in passing through, etc. As stated in the Yerushalmi and Rosh and Ran brought it; and we say: one gentile carries a barrel and Israel follows him full — forbidden, etc.; and even though we permit there when lacking, here it is forbidden as stated, for we are concerned lest… Rosh and Ran there in the name of Raavad; and as stated in the Yerushalmi there, it is not the end of the matter regarding full ones… Rosh brought it there; and unlike what Ran wrote initially that lacking ones are permitted like the barrel mentioned — (end).`,
      '5#א': `Even if he informed, etc. Variant there; and likewise in Tosafot there in the passage "no, etc."; and in Rosh there. (Extract) Even if none remained… even if he informed, etc. — Rosh there; and from this Rabbeinu Tam permitted Israel… on a festival, etc. (end).`,
      '5#ה': `And if the gentile, etc. As stated above siman 128 seif 5; and Tosafot there in the passage "he did not hand it over, etc."`,
      '7#ב': `Within, etc. In the Yerushalmi they asked to say: what is on the table is forbidden within the span of the hands; what is on the counter is permitted within the span of the hands — not so, said Rabbah in the name of Rav Sheshet: just as they gave the span of the hands for purities, so they gave the span of the hands for yayin nesekh; but what is said "on the table" is forbidden even outside the span of the hands; what is said "on the counter" is permitted provided it is outside the span of the hands.`,
      '8#ב': `Since, etc. Taz and Shach. (Extract) Since, etc. — in the responsum of the Rosh he wrote: even if he informed that he sailed — unlike the Rav; and likewise Taz and Shach (end).`,
      '9#_': `And specifically, etc. Beit Yosef inferred from the words of the Rambam cited there in Shulchan Aruch "and they went out, etc."`,
      '11#ג': `(Extract) And in a place… lest, etc. As the version that Tosafot wrote there in the passage "they opened." And some emend "many, etc."; and likewise the version of the Rosh there — end of passage (end).`,
      '11#ה': `And if it was, etc. Taz. (Extract) And if it was in part of them, etc. — as stated in Pe'ah (95a) "and because of this fool everything is forbidden"; we do not concern ourselves that just as he bought this he bought that — evidently every matter that if we did not find a counterpart it would be permitted, when a counterpart is found in one of them we do not establish prohibition on the others… Mordechai siman 1000, 338 — see there, where he expanded on this (end).`,
      '15#_': `He left, etc. As stated above 71a: to libate he has no time; and likewise here he is busy with it.`,
      '18#א': `Barrel, etc. From what is stated 24a "that one, etc." — let us say, etc.; and we hold like Rabbah, and even in proximity of a hundred — as above.`,
      '18#ג': `(Extract) And that it sits, etc. As stated 23b; and Rashi 24a in the passage "in the winepress, etc." — evidently even within the vineyard itself; and there we are concerned about passersby.`,
      '20#ב': `B'eh, etc.; and likewise; and the maidservant is not trusted. As stated in several places that the gentile is not trusted either to forbid or to permit; and even regarding Israel we say: whoever does not have in his hand, etc.`,
      '20#ד': `But thieves, etc. As stated 70a: if he was caught, etc.; and here she was not caught, etc. — as stated.`,
      '20#ה': `However, nowadays, etc. As stated above siman 128 seif 4 — so it should read; and as stated in the gloss; and as stated in the variant, namely in Mordechai there: that interest found in her hand and we lean to leniency — Rashi there explains because she was a minor; and further that here it is certainly intercourse, and therefore R. Eliezer does not purify, etc.; however it can be resolved whether we compare an adult who is now, etc. — see there siman 1, 334. And Tosafot 72a in the passage "that one, etc."`,
    },
    'mateh-yehonatan': {
      '1#_': `(Siman 129 in Shulchan Aruch seif 8 in Hagah.) Since the gentile did not know, etc. See Taz seif kaf-dalet and Shach seif kaf-alef, who wondered greatly at Rama, for in the responsum of the Rosh he wrote the opposite — even if he informed that he sailed it is also permitted; and it appears to me: Rashba wrote regarding one who brought wine in a wagon or ship, etc., if he informed that he sails to the bathhouse or synagogue it is forbidden; and what he wrote that we say "he heard the sound of a shofar blown for Shabbat" — if there is a roundabout way it is permitted, for we are not in the presumption of Shabbat observers as befits in the eyes of the gentile, and he trembles every hour lest he come now — so too here the gentile trembles every hour lest he come now; and he resolves: there regarding the sound of a shofar he trembles lest he remember the wine and come immediately, unlike regarding the bathhouse where certainly if he remembers the wine he will not come immediately from the bathhouse, for in any case he must stay a while to dress; and Raah wrote to resolve: granted there regarding the sound of a shofar that he went because of panic — we properly say he trembles lest he remember the wine and come; unlike here where he informed he sails with settled mind — he does not tremble lest he come now, since from the outset he went with settled mind. If so, according to Rashba who holds wherever he is not compelled to stay we say the gentile trembles — in our case even if he informed he sails it is also permitted, since there is no compulsion to stay; unlike according to Raah, who holds even where he is not compelled to stay, wherever there is no panic he does not tremble — here where he informed he sails it is forbidden, since there is no panic, for Israel thinks he locked with a key. According to this one can say the Rosh holds like Rashba — therefore even if he informed he sails it is also permitted; unlike Rama who holds like Raah and forbids if he informed he sails. Requires study.`,
      '2#_': `(There in Shach seif kaf-chet.) Even if most of the city's thieves, etc. Requires study, for in the Gemara they permit only because of double doubt, etc.; but when most of the city's thieves are gentiles there is no double doubt — see there. According to the quick reading it appears to me the Mechaber holds like the Rambam, who holds that what we hold "majority and proximity follow the majority" is not a certainty like a majority but is a safek — see there; and likewise Rambam in Laws of Yom Tov regarding a dove coop — see there. If so, here it deals when there is also a minority of Jews who are close to the wine, and it is majority and proximity which is a safek — and it is properly permitted because it is double doubt. But on this it is difficult at the beginning, where he said if most thieves are Jews it is permitted: if it deals when there is a minority of gentile thieves who are close, why should it be fully permitted — it should at least be forbidden from the side of safek, for majority and proximity is safek. Therefore one must say the Mechaber holds like the Rosh, brought in Asifat Zekenim chapter 1 of Bava Metzia regarding one who jumped from the counted ones into it — exempt from tithe; and they challenge: we captured them and they moved — it is "everything that separates from the majority separates"; and they answer: what we say "everything that separates" is not certainly from the majority but nevertheless is safek — therefore exempt from tithe, for the Merciful One said "certainly" and not safek. According to this, here since there is a small amount of Jewish thieves, therefore even though "everything that separates" is safek, and here there is another safek with it — it is double doubt. But above at the beginning, where there is one safek, nevertheless since most thieves are Jews, even if a minority are gentile thieves, it is not double doubt, for it is more to rely on Jewish thieves who are the majority than to rely on the minority; and regarding tithe the Merciful One said "certainly obligated in tithe" and this is not certain — unlike here where there is another safek with it: this safek of "everything that separates" is properly double doubt, for alone it would not be double doubt; and when I say another safek with it — there is double doubt. Requires study.`,
    },
    'nekudot-hakesef': {
      '1#_': `(Siman 129 in Shulchan Aruch seif 6 in Hagah) In the presumption of Shabbat observers, etc. And Ri Migash wrote that nowadays gentiles know that even if the Jew loses something he will not desecrate Shabbat — see there; and according to this one should be stringent.`,
      '3#_': `(There in Taz seif kaf-vav) It is astonishing, etc. Perishah and Bach already preceded him in this, and Perishah also concludes it is a scribal error.`,
      '5#_': `(There in Taz seif kaf-vav) For it is stated above seif 12 in Cheil, etc. And it appears to me there is a variant: there, since it is in an inn one returns the cork; but here the reason is as stated in Ran chapter 1 of Avodah Zarah, namely: if he had touched it he would not have bothered to return and seal it, but would take from the wine and go, or bring it to his house — end of his words; and likewise Taz; and specifically when it was sealed, or even corked with wood — for if gentiles found it and opened it, why should they return and cork it, since they left it to be lost, etc.; and likewise Beit Chadash like Rama.`,
    },
    'siftei-kohen': {
      '1#י': `If the barrels are open, etc. And for us there is no concern for touch unless he has benefit, such as drinking or exchanging — as above siman 128 seif 4 in Hagah; and in siman 130 seif kaf-chet I wrote in the name of Beit Yosef that in a small hole, even though they can draw from it — as long as they cannot insert into it — there is no concern for exchange, and it is straightforward. And see in the responsum of Mahari Beit Chad leket siman 200 regarding these rulings.`,
      '4#_': `If the barrel is corked. It implies that if it is not corked it is forbidden, for touch is not feared from passersby; and Bach wondered at the Rav here who was silent like the Mechaber; and above siman 128 seif 4 he wrote in Hagah that nowadays, since they are not idolaters, even open we do not concern lest he touch unless he drinks or has other benefit. Requires study: if so, everywhere the Mechaber wrote forbidden in benefit it should be difficult — for nowadays gentiles are not idolaters, it is permitted in benefit, as above siman 123; and likewise in siman 130 and 131 — in all these simanim it must be that nowadays it is permitted in many places since we do not concern lest he touched to libate where he has no benefit; and the Rav emended nothing there. And likewise in many places. But certainly since the Rav wrote in the main place of the ruling that nowadays it is permitted — it follows that everything the Mechaber wrote is only according to his view from the side of law; and is a merchant to calculate and go? This is straightforward. And above siman 131 seif kaf-vav.`,
      '6#א': `The wine is permitted. The gentile fears to touch lest he say "now he will remember his wine and come" — Tur from the Gemara. And according to this explanation it implies that even if the Jew goes to drink and the gentile knows his intent to sail — nevertheless it is permitted because he thinks when he remembers his wine he will immediately repent and come; and likewise it appears explicitly from Rashba and Tur and Raah regarding whether we say "he will remember his wine" in matters impossible to do here — as in the small seif after this; and likewise from the words of the Acharonim.`,
      '6#ב': `And Rashba wrote in Tosafot HaRosh that even open wine is permitted; and Beit Yosef brings it; and likewise in the responsum of the Rosh kelal 19 siman 13; and Beit Yosef and Darkei Moshe bring it and conclude unlike Ran in chapter HaSocher who wrote it deals here when the wine is corked with a cork — until here his language; and unlike the Derishah seif 28 according to the Tur.`,
      '7#_': `The wine is permitted. For the reason mentioned; and since the Mechaber did not distinguish, it follows he goes according to his method that he agreed in Beit Yosef with the Tur who challenged Rashba, who wrote that in matters impossible to do here it is forbidden when informing he sails; and he holds that since the reason is "now he will remember his wine and come," there is no distinction in any matter where one can say so — even though impossible to do here he does not want to lose his wine on his account — end. And likewise Bach that the Tur's words are reasonable words (and in responsum Masat Binyamin siman 29 he distinguished that we are not concerned when informing he sails except when he informed explicitly; but here even though the gentile knows he sailed, as long as he did not tell him explicitly he did not rely, for he says "now the Jew will remember, etc." — end; and it is difficult: what of it — safek, he knows he sails; and likewise in responsum Mahari Beit Chad part 2 siman 200 page 93 top of 93: when they went from ship to another ship, need not inform he sails, for he sees he sails; and likewise proven from Raah below that one need not distinguish in this). And Derishah this siman expanded greatly why we do not permit above when he saw he went to the bathhouse and when informing he sails; and he brought the Tur's language and the mishnah's explanation; and he also went down to distinguish distinctions that are not accepted; and likewise Bach here entered with forced interpretations — see there; and it is simply hidden from them the words of Raah in Beit HaBechirah 145b who also challenged Rashba that even impossible to do here is permitted; namely: for prayer in the synagogue he goes, and immediately it is impossible for him here; but these matters are decided from their place, for we say: he heard the sound of prayer — he got up and left; he heard the sound of a shofar — he got up and ascended — this proves this Israel, because he heard these sounds, got up in agitation like a hurried man; and now one can hang and say: because of his agitation he does not remember his donkey — for if he remembered he would not go neither to prayer nor to sit, for he does not lose his donkey now lest he remember — he abandons all and comes to guard the wine; but whoever separates from there without agitation but with settled mind — forbidden, whether bathing, whether prayer — and these are reasonable words and clear matters — end; and they are fit for one who said them; and this appears clear in my humble opinion according to the Tur.`,
      '8#_': `Since he did not know, etc. Likewise in Darkei Moshe in the name of responsum of Rosh kelal 19 siman 13; and likewise recorded in Shulchan Aruch; and it is astonishing, for explicitly in the responsum of the Rosh there the opposite — even if he knows he sails the Jew; and: it appears to me the wine is permitted; and proof from the last chapter of Avodah Zarah: that Jew and gentile sitting in a boat and drinking wine; Israel heard the sound of a shofar of the synagogue — he got up and ascended; Rava said: the wine is permitted. I would say the gentile said: now he remembers his wine and comes; and if because of Shabbat — he told me "the prohibition of a convert: when I was among Arameans I said Jews do not observe Shabbat" — and all the more in this case it is permitted, for the gentile will say: now the Jew remembers he did not lock with a key and comes; and according to one opinion, if he did not inform the gentile he sails it is permitted, for the gentile will say: now he comes every hour and trembles; but even if he informed the gentile he sails it is permitted, for the gentile will say: when the Jew remembers he did not lock with a key he will return home and lock, and the gentile trembles, etc. — end; behold explicitly even if he informed he sails it is permitted. And in truth it is recognizable that before the Rav was the responsum of the Rosh old Venice edition printed in the year 512, where this language is written; and all the more in this case it is permitted, for the gentile will say: now the Jew remembers he did not lock with a key and comes; and according to one opinion if he did not inform the gentile he sails it is permitted… when the Jew remembers he did not lock with a key he will return home and lock and the gentile trembles, etc. — end; and these words appear misplaced; and the Rav emended specifically: if he did not inform the gentile he sails it is permitted; but the truth will teach his way that also in the old edition — meaning like the new Venice edition as I copied above; and further that the Rosh brings proof from that Jew and gentile who drank wine, etc., and there even when he informed he sails it is permitted because the gentile will say "now he will remember his wine and come" — as written in seif kaf-tet; and further that according to the reason the Rosh wrote that the gentile will say when the Jew remembers he did not lock with a key he will return home and lock and tremble — certainly even if he informed he sails it is permitted for this reason; and likewise from the words of the Mechaber. Requires study.`,
      '9#א': `And an opening from the upper story to the house. It can be seen by all; if not, this side and that side are forbidden; and likewise Rashba, Beit Yosef, and Darkei Moshe; and it is straightforward from above siman 128 seif 3.`,
      '11#ד': `Even if most of the city's thieves, etc. Likewise the Tur; and requires study, for in the Gemara they permit only because of double doubt; and Rashi: safek gentiles safek Jews; and we lean gentiles lest they opened only for money, and when they saw it was wine they left — evidently it deals only with safek gentiles and Jews, namely when gentile thieves and Jews are equal; or when unknown whether majority gentile thieves or majority Jewish thieves; but with majority gentile thieves — no, for there is no double doubt, since majority are gentile thieves; and so appears from the words of Rabbeinu Yerucham; and one can resolve with difficulty — I shortened since this law is not common among us, for it is not customary to hide money in wine barrels — as the Rosh wrote. Taz wrote: and likewise thieves who pierced a barrel with a knife and in their hand a pot and drew wine into it — some say the wine inside should be permitted because of double doubt lest because he is agitated with this pot he did not touch the wine but immediately when the knife passed the thickness of the walls the wine came out and he did not touch it with the knife; and we lean he touched with the knife since the thief did not intend except to pierce so wine would come out and did not concern himself with touching — it is his force without intent and permitted; and one may be lenient nowadays since they do not libate — until here his language. It appears from his words that if it is known he touched with the knife it is forbidden, for there is no double doubt; and his words are astonishing, for never will one find such double doubt, for with that reason alone — since he did not intend except to pierce — it is permitted; and in truth he understood thus from Mordechai's words that Beit Yosef brought, who permits because of double doubt; and it is not so, for his conclusion is to permit from that reason alone even in the time of the Gemara; and likewise the Rav above siman 124 seif 24 permitted from that reason alone — since he did not intend except to pierce the barrel, it is gentile touch through something else without intent and permitted — end; and it was already explained there that gentile touch without intent through something else is permitted even according to the law of the Gemara — see there.`,
      '12#א': `Even if they are corked. Corked ones are like open ones, for when he returns the cork it is not out of fear but out of propriety. Ran and Rivash there.`,
      '20#א': `Permitted. See Rivash that Beit Yosef brought — permits for several reasons; and at the end wrote: all the more in this case, since the gentile was not found beside the wine nor inside the storehouse — we have no reason to believe he or another entered there; and above siman 130 end of seif kaf-chet in Hagah: if a wine barrel was with the gentile and he said it was dripping and they fixed it and he touched it — he is not trusted; and see in responsum Maharil siman 38.`,
      '20#ג': `Siman 125. So it is in the books and in Taz; and likewise in Darkei Moshe; and I know no reason for it here; and it appears to be an error — it should read siman 124 or siman 128; meaning there seif 4 was explained that we do not concern lest he touched to libate except when he touched for his benefit; since gentiles nowadays do not libate — if so, here too we do not concern lest she touched intentionally by hand to libate; there seif 24 was explained that nowadays gentiles are not idolaters — even if she removed the spigot intentionally it is permitted since she had no intent to libate — it is gentile touch through something else without intent; if so, here too we do not concern lest she touched by hand the wine in the barrel or touched what came out by what she drew, for then what is inside is also forbidden through the stream, since she need not do so; and likewise explicitly in Mordechai there, who concludes from the act of hiding the key above; and even if the maidservant drew and the spigot goes outside the reed — if the maidservant does not know, it is her gentile force without intent — end; evidently we do not concern lest she touched by hand, but require that the maidservant not know, for otherwise it is her force; but for us, who hold above siman 124 that his force and gentile touch through something else is permitted nowadays — if so, here too; however this is specifically in a place of loss — as written there seif kaf-alef.`,
    },
    'turei-zahav': {
      '1#א': `One who leaves a gentile, etc. In the Gemara he makes a distinction: if it taught "one who passes his wine" one would say specifically in this it is permitted, for the gentile thinks perhaps he will come and see me; but in a wagon or ship, if he sails he does as he wishes — meaning one would say we should concern for this; it teaches us we do not concern for this. And if it taught wagon and ship alone, one would say because he thinks perhaps he will come another way and stand by the wall and see me; but in a shop he closes the door and does as he wishes — it teaches us we do not concern for this. And all those above siman 128 — if he closed the door it is forbidden — that is when we know clearly he closed the door in a matter the Jew cannot enter there without the gentile's knowledge; but when we do not know — permitted; and even though there is a lock inside he could lock if he wished; nevertheless we learn: if here the gentile clearly closed the door it is forbidden, since he has connection in the house and has where to rely — standing there with permission, for Israel left it there; and likewise in the permit of wagon and ship that we say the reason of the permit is he thinks he will come another way and stand by the wall and see — evidently specifically when there is another way; but if there is only one way, since he sailed his eyes are from him it is forbidden, for he cannot come unless he sees him; and likewise if he clearly sailed on a ship or wagon in a place impossible to see — certainly forbidden; but when uncertain we do not concern for this. All this from Rashba in Tosafot HaRosh; and this is what he concludes here — and that it was not known, etc.`,
      '1#ב': `In another matter — when there is a roundabout way. In the Gemara they say: this is on one who passes his wine; and the same is the third case the Tur and Shulchan Aruch mentioned at the beginning of the siman; and Beit Yosef wrote in the name of Ran that specifically regarding one who passes they say so; but regarding one who leaves a gentile in a shop and Israel goes in and out — we do not require a roundabout way, for every hour he fears from him lest now he come and see Israel approaching the barrel; and Rashba wrote regarding wagon and ship that we require a roundabout way as I copied above; and Beit Yosef wrote that Ran also agrees to this, and he only limits one who leaves a gentile in a shop — for presumably Israel can come there suddenly; however if Israel cannot come suddenly to the shop, such as when there is a window on the opening that the gentile can see from it if Israel comes — it implies it is forbidden, for he no longer fears — end; and I wonder at the Rav's words where he wrote that if there is a window, etc., it is forbidden — on the contrary, since there is a window the gentile trembles lest Israel come and be seen through that window — as written in Shulchan Aruch siman 128 seif 3; and even if you say the wine is not placed opposite the window here — nevertheless it is difficult, for above siman 128 seif 3 he wrote: if there are holes in the door and Israel cannot see — permitted, for prohibition is only if he closed the door with a lock from inside; but if there is no closed lock, all wine in the house is permitted and trembles, and there is no prohibition because the gentile can see through the holes; and why should it be forbidden here when there is a window if not clearly that he closed the shop — behold this is exactly the law above; and it appears to give a reason why in truth they said specifically regarding one who passes and on a ship that requires a roundabout way — because they are in the field, an open place, and therefore wherever there is only one way the gentile can be careful whenever he sees him going from afar and he cannot come quickly; but in a house or shop it is possible he went a very close way to one of the houses and quickly as in the blink of an eye he will come and see us and trembles — therefore here we do not need a roundabout way, only in those two — wagon and ship and one who passes his wine; but at the beginning regarding one who leaves in a shop — no. And it appears straightforward that also regarding one who passes wine between houses the law is the same, and a roundabout way does not apply there; and always the gentile trembles lest he suddenly come upon him; and they were stringent only in a place open from houses and there is only one way — so it appears in my humble opinion straightforward, even though in Perishah he wrote it applies only to the third gate alone where he passes; nevertheless it appears as I wrote that it applies also to the middle one, since Rashba wrote thus in explanation; and one reason fits both.`,
      '4#_': `Many passersby. Likewise Rashba; and Tosafot chapter HaSocher (90a) also wrote in the name of Rashbam to be lenient if it is a public thoroughfare — even a gentile; and he wrote we do not concern lest perhaps he touched, since nowadays libation affection is not upon them; and they conclude on this — namely specifically with a narrow hole; but in a jug or cup with a wide opening it is easy to touch and customary to touch them in the manner of one occupied — end; and Beit Yosef brings them; and Darkei Moshe wrote there is a dispute between Rashba and Rashbam: according to Rashbam it need not be corked, for then even with a wide opening it is permitted; and in Derishah he wrote to distinguish that wherever there is libation affection upon it like according to Talmud law, Rashba requires it be corked even in a public thoroughfare even with a narrow hole; but Tosafot deal with nowadays when there is no prohibition because of libation but lest he exchange for his benefit — permitted when open as long as the hole is narrow; and so appears to me the essence, that also nowadays when there is no libation affection, nevertheless wherever touch is nearly certain it is forbidden even nowadays — as Beit Yosef wrote in the name of Rashba at the beginning of siman 128 regarding wine stored with a gentile; and therefore also here with a wide hole it is nearly certain he touched and forbidden even now; and therefore Rama ruled well in siman 128 seif 4 to distinguish between narrow hole and wide in our time.`,
      '5#ב': `And he fears to enter it. And it is not similar to one who leaves his wine in a city of gentiles without key and seal — for here other gentiles tremble from the gentile, and he trembles from them lest they tell Israel who entered. Beit Yosef in the name of Ran. And what he wrote in seif 6: and Israel heard the sound of shofar blowing — Rashba in Tosafot HaRosh challenged: if so, why did he forbid above when informing he sails — let us say he remembers his donkey and comes, for when he goes to sit Shabbat and to pray he is like informing he sails; and he resolved: they did not say "he remembers his donkey" except when sailing in matters possible to do here, such as prayer and Shabbat observance — for when he remembers his wine he comes and does here prayer or observes Shabbat; but when sailing in matters impossible to do here, such as sailing to bathe in a bathhouse and the like — forbidden; and further study is needed on this — end; and the Tur disagrees with this and wrote: since the reason is because he remembers his wine, in any matter where one can say so — even though impossible to do here — nevertheless he will not lose his wine on his account — end; and one must resolve Rashba's difficulty according to the Tur; and it appears he resolves the difficulty another way — and it is a clear matter in my humble opinion that in those two cases in the Gemara — namely that where he heard the sound of Shabbat rest and prayer sound in synagogue and went — not for nothing did they mention this, and did not say he went on his own for these matters without arousal by another; but certainly specifically in such a case where he does not go on his own but suddenly by chance, and therefore his wine is forgotten; the gentile sees this and therefore trembles lest he return and remember his wine — unlike those at the beginning of this siman when informing he sails, where he certainly consoles himself before leaving and the gentile thinks he intentionally left his wine with him and trusts him — therefore he does not tremble; and afterwards I found this resolution in Raah in Sefer Badek HaBayit, and Rashba in Sefer Mishmeret HaBayit rejected it with a rejection that has no substance to any viewer of his words in this; and proof to our words from what is written nearby seif 9 "and they both went out in panic" — the essence of the law depends there on this as will be explained nearby; and that we learn from what they said there in the Gemara that the incident was thus — and if so, here too let us say thus, since it was mentioned in the Gemara that the incident was thus — certainly the matter depends on this. And with this I further resolve what was difficult in what he wrote in seif 1: if he said to the gentile "you pass and I will come after you" — it is forbidden; it is difficult: why not say the gentile trembles lest he remember his wine and come quickly after him; according to Rashba's resolution I do not know how this will be settled; and according to what I wrote it is resolved: the beginning of this siman certainly deals when he left it intentionally, and the essence of the matter there is whether the gentile thinks Israel trusted him the wine — and therefore it is forbidden when informing he sails; therefore if he says to him "go and I will come after you," the gentile sees he trusts him the wine since he tells him to go with the wine and not go with him to guard it — why should Israel's mind change afterwards, since he did not leave in panic — change of mind applies only when he leaves not by himself but by others, or leaves unintentionally and possibly afterwards he will remember and regret. So it appears clear in my humble opinion; and I saw other resolutions on this that are not acceptable at all and need not be answered.`,
      '9#_': `And specifically that they went out in panic. So is the opinion of the Rambam; and they learned from what we say in chapter HaSocher in this incident: they heard the sound of a merchant — they went out, etc.; since the Talmud mentioned the incident was thus — learn from it the matter depends on this; and I already wrote according to the Tur — and he is the essence — that also in the incident where he heard shofar blowing and heard them calling to synagogue it is specifically so; and the reason here is specifically they went out in panic — Beit Yosef wrote: if not through panic one should concern lest he saw the Jew in the market and left him there and came home to libate and is not afraid, for he left him in the market; but when they go out through panic, sometimes a person leaves his friend in the market and when he comes home finds they preceded him home — from the panic one passes before him and he does not notice him; therefore he concerns lest the Jew preceded him — end; what he wrote that without panic one should concern lest he saw him in the market, etc. — I wonder: from uncertainty do we forbid wine? And what difference from that case siman 128 seif 3 where from uncertainty we do not say he locked with a key even though there is a bolt inside; and as proven also at the beginning of siman 129 as we copied there — except it is clear they did not forbid stam yayin until the prohibition is clear, as proven also from the mishnah where he did not inform he sails and we do not say perhaps the gentile thinks Israel sails as is the truth; and likewise in seif 10 we are lenient from uncertainty; and likewise in many places. Also what Beit Yosef wrote: if they went out in panic even though he saw him in the market he does not notice him — this is excessive leniency, for the gentile's entry was not in panic but the exit alone; and many times a person goes out alarmed from the sound of noise outside and when the noise subsides his mind settles — all the more here where it states the panic was because of a bridegroom or a funeral: when he returns home there is no panic here; and the Talmud's author and poskim should have mentioned that the entry was also in panic — therefore it appears in my humble opinion that what it states "they went out in panic" is because of a negative commandment that the wine is forbidden — the gentile does not tremble that the Jew guards the wine; for if he does not trust the gentile, why did he go outside and abandon his wine and not fear lest the gentile lock the door as he actually did and libate his wine — for he has connection in the house; therefore they required he went out in panic and did not remember his wine at that time and the gentile concerns lest he already remembered his wine and came home; and according to this, if the gentile saw him in the market at the time of his return home — clearly the wine is forbidden whenever the gentile closed the door from inside, even though the exit was in panic; and we do not say the panic causes him to concern lest he did not see well — we have no proof for this leniency even though at entry he was still in panic; and without panic there is no place to be stringent from the side of lest he saw him in the market, for from uncertainty we are not stringent except because the gentile thinks the Jew trusts him — for otherwise why abandon his wine; and even though at the beginning of this siman regarding leaving in a shop and not informing he sails it is permitted — there it is different, for we do not know clearly he closed the door — we say he did not close it and trembles lest he come; unlike here where we have a counterpart before us that the door is certainly closed — only that we should permit because Israel already preceded to the upper story; if there is no panic at time of exit the gentile says: since he went with settled mind he certainly remembered then his wine — why would he precede himself so much; therefore we are stringent since the door is closed before us; therefore they required the exit was in panic and he did not remember his wine and already remembered and preceded himself. So appears clear in my humble opinion.`,
      '11#ב': `That the gentile's path does not interrupt it. The Rosh was stringent and wrote we require specifically locked at night — as Beit Yosef wrote; it appears straightforward Rashba agrees it is permitted; and Maharach wrote that in great loss one may rely on Raah who permits on the gentile's path that interrupts it and it is locked at night; and it is without precision — for here everyone holds it is permitted, and even in minor loss, for whatever is locked at night is preferable to no gentile path interrupting it; and this is straightforward.`,
      '11#ה': `That there are known thieves. With this Rama resolves Mordechai's words that Beit Yosef brought, who holds even if it is known there is one Jewish thief it is permitted; and in the Gemara Rava permitted because of majority of Jewish thieves; so Beit Yosef challenged; and in this division of Rama — see what is written siman 114 seif 10 that contradicts Rama's words here; and in truth the essence is as written here.`,
      '16#_': `And the beams are separate. It is astonishing why a distinction of beams was needed here, for in any case the roofs are separate from each other and the Gemara did not mention a distinction of beams; and it appears "and separate" is like "or separate"; and so it is explicitly in Rambam chapter 13: after mentioning distinction of the courtyard by the heads of the beams, namely: and likewise two roofs where Israel's roof was above and the gentile's below, or they were side by side and there is a partition between them, etc. — end; that also with roofs sometimes there is law of distinction of beams; and this is straightforward; and in all this the reason is the gentile was caught as a thief.`,
      '17#_': `And specifically when it is sealed with a cork. Rama learned this from what Ran wrote in chapter Elu Metziot here, that it is permitted even for drinking what he finds, and we do not require a seal — for here it is different: if a gentile had touched it he would not have bothered to return and seal it, but would take wine and go — therefore whatever we see sealed is permitted — end; it implies open ones are forbidden; and it appears to me that even if sealed with a wood cork it is forbidden, for it is stated above seif 12 in Cheil who entered the city that wood corks are forbidden — it is propriety that they return a wood cork there without bother; and these are also Ran's words in chapter HaSocher; except perforce what Ran wrote in chapter Elu Metziot that the sealing is proof they did not touch — namely sealing with clay; and from this contradicts what Rama wrote: if it is sealed with a cork — meaning of wood — it is permitted and forbidden only when fully open, for we proved the permit is only with clay specifically.`,
      '18#_': `And all the more when there is no fence of, etc. It is difficult why he wrote this "all the more"; and further difficult that the Tur concludes with this reason "we lean there is no way to steal from this vineyard and hide inside it" — end; and it is difficult why I need this reason, for in any case it is forbidden. (So it should read; and so in the Tur. And in most books the version is "permitted" — this is corruption; and what he wrote "and in the Gemara, etc." — and he rejected it through rejection lest the permit is because there is no way to hide, etc., because in the Gemara it deals with found in an orlah vineyard and around the vineyards is the permit — and this is the end of that law; and likewise to be lenient, etc., for one reason for both. And the examiner will find:) Because of majority and proximity we follow the majority; and in the Gemara he sought to give a reason in truth because of majority and rejected it through rejection lest the permit is because there is no way to hide inside it; and since we hold in truth we follow the majority — why did the Tur write the other reason? And it appears this "all the more" deals when the vineyard is completely separate and around it is neither Israel's vineyard nor gentile's vineyard; and he did not state there is no Israel's fence, but the essence of the permit at the beginning is because of surroundings that are Israel — he said here that if that permit is not there and the vineyard is separate on every side from vineyards — if so, we follow this vineyard; and as written above siman 11 in the name of Mishmeret HaBayit it teaches us that on the contrary it is more straightforward to forbid for another reason that there is no, etc.; and this reason applies more to a solitary vineyard where there is no way to hide the theft from it, for the vineyard owner will surely notice when he finds it, since he takes from it — therefore the language "need not say" is well settled.`,
      '20#ד': `However, nowadays, etc. This applies to that law he stated at the end alone — since there is presumptive evidence, etc.; and likewise explicitly in Darkei Moshe, namely: therefore it appears one should not permit in such a case except nowadays — end; but at the beginning regarding permitted because the maidservant is not trusted — it implies; but if she certainly drew wine through the spigot it is forbidden — this is even for us — as written in siman 124 regarding piercing a barrel with a knife — see there.`,
    },
    'yad-ephraim': {
      '1#_': `There is a roundabout way. Avodat HaTalmid and responsum Chayei Olam Yoreh Deah siman 173 on an incident where they all went to synagogue on Yom Kippur night and left an open wine cellar and the maidservant remained in the house; and the synagogue was far from the house about twenty amot; and he expanded on this and concluded to permit in benefit — for exchange we do not concern; and for touch for its sake we concern only for drinking need; and since it is grape juice within three days they did not drink; and combined with several poskim who are lenient — one may be lenient in benefit at least — see there.`,
      '6#_': `And the storehouse opening was closed. See Avodat HaTalmid and Shibolei HaLeket part 2 siman 72: Israel rented a cellar from a gentile and there was wine in it with key and seal as required; and the gentile's house was opened and also the cellar; and in the morning a small maidservant felt alarmed and ran in panic to the Jew and informed him; and he went and found the barrels sealed and full and no moisture around — no concern at all; and see in Beit Yosef siman 129 and in responsum of the Rosh "forgot to close the key, etc." — see there regarding a gentile found in the cellar where there were sealed barrels and he opened one of them; and when the Jew came he remained between them and the Jew saw him — one must forbid, since the barrel was sealed and is found open — as explained in siman 129 seif 11 in Hagah; and another case where he found a nursing woman bent over the barrel — we do not rely on a usual matter and one should be stringent even though it is touch through something else and stream — as explained in siman 124 — see there. And he wrote in responsum Beit Yehudah siman 12: Israel had a closed room with several wine barrels; a gentile servant came and told the master he found the opening open; the master went there and found the barrel bodies open and spigots with reeds in them stained red wine; he struck him to confess and he confessed he and his gentile friend did this; he searched and found in his tools a bent nail like a key; and he wrote based on responsum of Rivash that Beit Yosef brought siman 127: and Rivash wrote unless there is proof he touched the wine that was open and became sealed — nevertheless he forbade only when found standing beside the wine (and in truth from Rivash's responsum it appears it does not deal thus — requires study); if not — it is safek; or perhaps Jews entered and stole — as written siman 128; and the gentile's admissions that he opened the key and drew the wine — we hold the gentile is not trusted to forbid; and even Israel is not trusted when it is not in his hand — as written siman 128; and see in Rama siman 110 seif 8; and even though here certainly the wine was opened and a hand was sent in it — nevertheless since but for the gentile's words it would be permitted, since he was not found standing beside the wine combined with the counterpart — one does not forbid because of the gentile's words — see there. And in my humble opinion requires study here, for there is presumptive evidence — I shortened.`,
    },
  },
  130: {
    'baer-heitev': {
      '2#_': `He designated. Then it is like the Jew's courtyard — therefore permitted in benefit — Taz. And he further wrote: even a key alone is like one seal (and I already wrote above siman 118 that Nekudot HaKesef challenged him that a key is not like one seal); and also sealing the barrel body is not like one seal except in great loss; and if he sees the seal damaged one forbids only when it appears hidden intentionally by a person — as below seif 8 in Hagah — end Shach.`,
      '10#_': `Permitted. Everything that can be seen through a hole and crack — as above siman 128 seif 3; and Taz wrote: but with the door fully open it is permitted even at night, for he trembles lest now he remember his wine and come — likewise Rashba.`,
    },
    'beer-hagolah': {
      '1#א': `Braita Avodah Zarah 31a; and according to Rashba the correct version in R. Eliezer's words is key and seal; and R. Eliezer's position makes key and seal like two seals; and it was decided there in the Gemara the halachah is like R. Eliezer; and so appears the opinion of Geonim and Rif in their laws — as the Tur wrote in their name.`,
      '1#ב': `Tur in the name of responsum of R. Yitzchak bar Yehudah to Rashi.`,
      '2#_': `Rambam chapter 12 of Forbidden Foods.`,
      '5#_': `Tur; and likewise Rashba in the name of Raavad.`,
    },
    'beur-hagra': {
      '1#א': `Permitted, etc. For the whole passage there implies it requires two seals; for Rava said there "a barrel on its mouth…"; and there 29b R. Eliezer came to teach us, etc.; and there 39a R. Yehudah: a barrel, etc.; and Rosh chapter 2 seif 4; and it should read that they explain, etc.; and even though the Rosh wrote this explanation is forced and Ramban also challenged, etc. — they already resolved in Tosafot HaRosh beginning gate 4 — see there; and: or key and seal. (Extract) Permitted, etc. — Geonim who explain Rashba and Ran that Rif ruled like R. Eliezer; and likewise Rif explicitly in chapter 4; and we hold like the first Tanna who follows R. Eliezer, etc. (end).`,
      '1#ב': `(Extract) If it is, etc. See there 62 that Rambam's opinion is not like Rashba and Ran; and it should read he explains what is written (69b) because of "he will come" — therefore requires two seals; for even R. Eliezer agrees (and likewise Ramban in his novellae chapter 2 in the name of Raavad and contradicted — see there); and therefore Rif wrote first and we emend in chapter HaSocher, etc., because of "he will come" and afterwards wrote R. Yochanan's words "two seals"; and requires study (and above seif kaf-chet he wrote Rambam ruled like the Rabbis) (end).`,
      '1#ג': `And this is only, etc. See Tosafot 31b in the passage "The sender." Rivash wrote to Rash in a responsum, etc.; and the Rosh there.`,
      '1#ה': `And some permit, etc. As stated 69b; and since we hold like Rashbag, etc. — there. (Extract) And some permit, etc. — in Tosafot 69b in the passage "what is the reason." However it appears to R. Yitzchak there is no distinction, etc. — end of passage (end).`,
      '1#ו': `Provided, etc. In the aforementioned Tosafot in the passage "The sender"; and there 71a in the passage "what is the reason."`,
      '2#א': `If he deposited, etc. Gemara 31a; and as above. (Extract) If he deposited, etc. — Rambam; and as stated 31a and like the Rabbis; and Rashi there in the passage "he designated, etc." and in the passage "and the Sages, etc."; and from this it is proven Rambam ruled like the Rabbis; and his version like our version there "key or seal" — unlike Ran (and therefore Rambam did not mention key and seal except in that braita there 61b; and he holds specifically there key and seal help; but according to Geonim and Rif's version it follows R. Eliezer; and according to Tosafot's version it follows even the Rabbis (and above seif kaf-tet and siman 131 seif zayin); and Tosafot 31a in the passage "and both of them" who hold key and seal are two seals). And what he ruled like the Rabbis even though Rav ruled like R. Eliezer — because R. Yochanan and R. Elazar hold not like him; and Rav retracted there 39a; and Rav Ashi there 29b; except that there 69b is difficult: we say "since, after all…" and the halachah, etc.; and it appears he explains all this is from Rava's words like all those statements there even though he said 31a "a barrel on its mouth" to explain the Rabbis he came and his words were rejected from Rav Ashi and Rav and Shmuel 39b — as above. And Rif and Rosh and end of passage omitted this law that they explain like Tosafot's explanation there in the passage "one who deposits, etc."; and one can say Rivav follows his reasoning, etc.; and we do not hold like Rivav; and likewise according to Geonim and Rif's version that Rashba and Ran emended "and key and seal" and explained like R. Eliezer — namely he designated this corner locked with key and seal and it is permitted for drinking (end).`,
      '2#ג': `And he need not, etc. See Tosafot there in the passage "The sender"; and Rabbeinu Tam, etc.; and there 69b in the passage "what is the reason, etc." (Extract) And he need not recognize, etc. — Tosafot 31b in the passage "The sender"; Rabbeinu Tam's explanation; and b'di'eved, etc.; and in Tosafot 69b in the passage "what is the reason." However since here in our sugya we hold like R. Eliezer, etc.; but b'di'eved, etc. (end).`,
      '3#א': `And likewise wine, etc. For this is the alundit there; and Rosh there; and even according to Rabbeinu Tam's explanation, etc. — from the precision of the beginning, etc.`,
      '4#_': `(Extract) How, etc. Rashi explains there "a barrel on its mouth of a barrel — smeared and sealed" — meaning a vessel smeared and attached to the barrel; and smeared and sealed is one matter, like sealing its mouth downward, etc. — it is a knot; and likewise "he tied and sealed" is one matter and it is one seal; and the barrel body itself attached with clay to the barrel is a second seal; and likewise a basket — and tightening is seal one and the body seal two; and what is needed here is tightening because it is not attached with clay to the barrel but the barrel enters into it; and likewise in a wineskin the knot of the skin is seal one and the knot of the strap seal two; and likewise in a pouch its mouth requires two knots; but Rambam explains "a barrel on its mouth of a barrel" — the vessel is the body for the barrel; smeared and sealed as Rashi explained is one matter attached with clay to the barrel as is the way of all bodies and it is seal one; except since the way of a body is not in a vessel and it is a change — it is two seals; and likewise a basket is also a body for the barrel; smeared and sealed — except since the way of a body is in a basket, therefore tightening is required; and this is the change that there is no way to be tightened: in a strap the strap is not tied only the skin; but the change that is in the strap and its mouth downward is like seal two; and likewise tying its mouth, etc. — also not tied downward but upward; and Rambam considers in the second instance from one that it is a greater stringency; and the first section of each includes in what is written "and likewise any change, etc."; and plastering or tying, etc. But Tosafot 69b in the passage "what is the reason, etc." explain: smeared is seal one and sealing is seal two (end).`,
      '8#ב': `And specifically, etc.; and even if, etc. In Semak and Semag they challenge what is stated 31b: and if not — forbidden; and even according to R. Yitzchak who returned and found it damaged — from what is stated in chapter 8 of Taharot mishnah 4 "one who leaves his vessels, etc."; and all the more in yayin nesekh — as stated in Avodah Zarah 72b: it was stated "courtyard, etc."; and Tosafot explain there in Taharot it deals with going out and coming in; and Tosafot HaRosh wrote: but in Semak and Mordechai they permit; and they brought proof from Tosefta of Taharot; and Rosh brought it there chapter 7 mishnah 7 "one who leaves his vessels, etc."; and it appears they do not disagree — Semak and Semag deal when seen hidden intentionally by a person, and therefore they brought from the mishnah there in such a case; but Semak and Mordechai deal where one can hang, etc.; and in such a case the Tosefta deals. But in Mordechai siman 1000, 334 he distinguishes between the depositor of the Gemara of Avodah Zarah and that of the Tosefta that does not deal with a depositor; and likewise Rosh there; and it is astonishing, etc.; and one can distinguish, etc.; and above end of siman 129 in Hagah.`,
      '8#ד': `And if the gentile, etc. See end of siman 129 in Hagah as stated; and see in Orach Chaim siman 16, 337 in Hagah.`,
      '9#א': `And even if there was also, etc. Tosafot HaRosh; and as stated below "if the gentile, etc."; and see what is stated.`,
      '9#ב': `(Extract) If it was, etc. Like the first Tanna who follows R. Eliezer — Rif and Rosh and Ran and end of passage. (Extract) If it was, etc. — like the first Tanna who follows R. Eliezer — Rif; and from here support for Rashba and Ran's explanation that Rif ruled like R. Eliezer, except he explains that key and seal are required as above; and he explains Rif's words: that the aforementioned braita "buyer or renter, etc." 31a — perforce deals in another courtyard, for otherwise key and seal are not required as written here; and if so R. Meir and the Rabbis here dispute the dispute of R. Eliezer and the Rabbis there; and what is written "and the Sages say: always forbidden" — it should read with key and seal; but with two seals certainly permitted according to R. Yochanan there. And according to Tosafot's method it deals here with key or seal; and likewise halachah like the first Tanna who follows R. Eliezer; and Ran; and siman 131 in Hagah (end).`,
      '9#ד': `Unless, etc. There he wrote some permit even in such a case — as stated siman 128 seif 2; but Raavad forbids since he rented, etc.; and Shach.`,
      '10#א': `In another matter, etc.; and specifically, etc. See Tosafot HaRosh there.`,
      '10#ב': `(Extract) And this is only by day, etc. Tosafot 61a in the passage "and a window"; and siman 131 seif 1 in Hagah (end).`,
      '10#ג': `(Extract) And therefore even by day if he locked, etc. As stated 71a "let the inn be locked, etc."; and likewise here he has where to rely that perhaps there is connection in the courtyard — as above "since, etc."; and Shach seif kaf-vav.`,
      '10#ד': `And there is no hole, etc.; but, etc. There R. Yehudah said: everything before, etc.; and above siman 128 seif 3 (end).`,
    },
    'pitchei-teshuva': {
      '2#_': `And specifically if they see. See in responsum Noda BiYehudah tinyana Yoreh Deah siman 72 regarding an incident where a Jew sent with one gentile with wine on the road and the Jew was not with him; and when he came with the wine the gentile said the seal was damaged by force when the wagon fell — and he ruled the wine forbidden; for even though Rama wrote that if one can hang that it was hidden, etc., it is permitted b'di'eved — that is where one can hang that the gentile did not notice and did not know at all the seal was hidden; but in our case the gentile knew it was hidden — even if we believe it was hidden by force, afterwards the wine rests in his possession and it is like deposited with a gentile without a seal. However this is specifically when sending with the gentile from place to place and on the road it was damaged; but if he deposited with the gentile and the Jewish depositor is present here and the gentile can tell him — we say presumably he immediately told him, for he fears and says in his mind: if I wait until the Jew comes he will suspect me that I damaged it intentionally to reveal — therefore he immediately runs and informs; and nevertheless he did not decide to be lenient except b'di'eved and in a manner that scholars agree with him — see there; and see in responsum Shivat Tzion siman 31 (and in responsum Chasam Sofer siman 254).`,
    },
    'siftei-kohen': {
      '1#ג': `And if he found a knife, etc. Darkei Moshe wrote: and what Avodat HaTalmid wrote that the wine is forbidden when he found a thorn stuck — above siman 129 and 124 there is reason to be lenient — end; meaning there it was explained that gentiles nowadays are not idolaters; and if they touched intentionally through something else, such as piercing there with the knife to draw wine — permitted in a place of loss; and likewise here; and according to this his words here in Hagah (and that we do not concern lest when he drew the wine he touched by hand the wine and what is inside became forbidden through the stream — why would he do so — as written end of siman 129); except what is written above siman 128 is a scribal error — it should read 124; and so in Taz.`,
      '9#ג': `And if the gentile does not live in the courtyard — permitted. Even though the Jew also does not live there — proven explicitly in Rashba; and likewise Bach; and it is straightforward; except he wrote this is specifically when there is one seal; meaning: from Rashba's words it is proven that even without any seal it is permitted for the reason that since he does not live there he is not expected to come there; and further that he wrote: whoever does not live in that courtyard — behold he is like another gentile; and regarding another gentile it was explained above siman 128 seif 4 that even without any seal it is permitted; and so proven explicitly in Tosafot HaRosh 126b — see there.`,
    },
    'turei-zahav': {
      '1#_': `And we are not concerned lest he draw wine from between the boards. For we do not hold like the first Tanna of Rashbag in chapter HaSocher who holds we are concerned for an orphan — Ran explains he will make a new hole; rather like Rashbag who is concerned only that he open the body, etc.; and it implies from here that if it was clear he drew wine from between the boards it is forbidden; and even though in siman 124 seif 24 Rama wrote regarding a gentile who drew wine by piercing a barrel with a knife — what is in the barrel is permitted — it is different there, for the knife is still stuck there; but if they already sealed it — certainly forbidden even for us, for at time of sealing he touches there where the wine comes out; and likewise from what Rama wrote nearby "and if he found a knife in a barrel, etc." — it implies specifically while it is still there; and likewise here in Darkei Moshe he wrote: if he found a thorn stuck there one may be lenient, etc.`,
      '7#_': `Sealing the barrel with clay. In the Gemara it is thus: Rava said "a barrel on its mouth of a barrel — smeared and sealed" is two seals; and if not — a basket and tightening is two seals; and if not — no; and Rambam explains this is the language of Shulchan Aruch; and the Tur: plastering — smearing with clay and drying is one seal in all cases; but without drying it appears it is not a seal, for very easily he can remove wet clay and put another in its place; and likewise Rashbam wrote in the Gemara that Beit Yosef copied here: "attached to the barrel and dried, etc." — end. And their way was to place some vessel on the mouth of the barrel when plastering it — for such is Rambam's language here as the way everyone seals; only if he inserts the barrel in a basket and tightens it, it is considered one sign since it is a change; and it is found in the Gemara this "a barrel on its mouth of a barrel smeared" is one seal and "sealed" — meaning he makes a second seal — whatever it may be — is two seals; but if he did not seal another sealing, it is only one seal, since their way was to place a vessel there at time of plastering — it is only as if there were plastering alone; and likewise the Tur's language is explained: he plastered the mouth of the barrel and sealed it — meaning he made a second sealing after the plastering; and what he wrote afterwards "and he inverted a vessel on it and tightened it" — this "and he inverted" is like "or he inverted"; and such is the way of language in many places — meaning: either he does not make a second sealing but inverts on it and tightens — that is also a second seal and joins to the plastering of the barrel mouth; and such is Rambam's language — Shulchan Aruch copied here only that the Tur did not mention plastering in the end of "tightening a vessel on it" and relied on the plastering of the barrel mouth that he mentioned at the beginning; and Rambam mentioned plastering on the tightening vessel — and the intent is one: all matters of plastering help whether on the barrel mouth or on the tightening vessel — so it appears to me clear and correct; and Beit Yosef did not descend to this and challenged several difficulties on the Tur and made a dispute between Rambam and Tur; and according to what I wrote nothing is difficult and there is no dispute here; and I did not need the forced interpretations I saw in explaining the Tur's words — let one who wishes examine them. And since Rama already wrote in siman 129 end of seif 1 that in sealed barrels it is permitted in any matter in great loss — if so, if the wine was in a gentile's possession without guarding and the barrel was bodied and plastered with clay and dried — permitted in great loss, for it is one seal and not bother and forgery; and it appears to me this is specifically when the barrel rests in the gentile's house; but if one conveys it on the road alone and knows the Jew sailed — plastering with clay does not help at all, for it is simple that because the wagon constantly shakes the wine goes upward and softens the clay and falls — a very common matter; and the way of wine carriers is to repair the clay constantly because of this around the body; therefore it is like fully open without a seal. And I saw in Masat Binyamin they asked about wine conveyed without Israel's guarding and the barrel was sealed with a vine tendril and around it plastered with clay and among the tendrils a thick tree branch was inserted to strengthen the sealing as is the way of new-wine carriers — and he permitted the wine because this is one seal — as Rama wrote siman 129 that I brought above; except he distinguished there if the wine ferments as new wine does and rises upward and spoils the barrel's plastering — and his words are astonishing, for then all new wine ferments and there is no way to do thus with tendrils except when it is still fermenting; and in essence of law there is no distinction between fermenting and not fermenting, for certainly also without fermenting the wine goes upward through the wagon's motion; and therefore it appears in no case is there permit in conveying wine because of plastering alone without another sign — only when resting; then plastering helps — so it appears to me.`,
      '8#_': `And likewise if the mouth of the skin is narrow, etc. In the Tur it is written: tie and seal the mouth of the wine skin and put it in a sack with the skin's mouth downward and tie the sack above — two seals; the skin's mouth upward is not two seals; and in the Gemara it is also: skin in a strap — tie and seal its mouth downward, etc.; it appears straightforward this "and seal" does not mean another sealing as I explained regarding "a barrel on its mouth smeared and sealed" — for here the sealing was conditional on the tying itself: granted regarding plastering there is no distinction since once it dried there is no bother to make another and wait until it dries — unlike regarding tying: whatever is not a strange matter is not a sign at all, for an ordinary tie certainly has no bother at all to untie; rather we certainly require a strange tie — as written nearby "two strange ties, etc."; therefore they said in the Gemara: if he tied and sealed — meaning he made a recognition in the matter of the tying — automatically it was one seal; and its mouth downward was seal two; or what he folded the skin's mouth inward — with this are also the Tur's words we mentioned explained: the tie of the skin was seal one because it is strange — he made it in the manner of sealing; if the skin's mouth was downward and the sack tie above — meaning an ordinary tie that is not strange — two seals; and as we mentioned, so it appears to me to explain the Tur's words also here; settled what Beit Yosef inferred on the Tur here; and according to this putting in the sack was no seal — only the tie and inverting the skin's mouth or folding its mouth inward was two seals; and it appears the reason is: whenever the skin is in a sack and its mouth upward, immediately when he unties the ordinary sack tie the skin's mouth is exposed as if without sack — therefore when the Tur wrote "but he folded the skin's mouth inward" — even though its mouth is upward in the sack it is two seals — likewise if it is without sack at all; and as Beit Yosef and Shulchan Aruch wrote here from Rambam's language who did not mention putting in a sack at all and did not write "even though its mouth is upward" but since at the beginning he said if it is in a sack upward it is not a seal — here he said it is permitted here even though there is no seal because of putting in the sack; and Maharach ruled because of the Tur's language that putting in a sack is required at least; and it appears to me since from Rambam it is clear we do not require a sack and Shulchan Aruch brings it — we have no reason to dispute his ruling, since in the Tur it is not proven a sack is required; and that Shulchan Aruch seif 1 wrote "put the skin in a sack, etc." — there it deals with wood as explained there, and one should concern lest he draw wine through its boards; and nevertheless Rama concludes there one is accustomed to be lenient; but if the skin is of leather and its stitches are not visible from outside — it appears clear we do not require putting in a sack, only two seals as I explained; and the tie was also a seal — namely it is somewhat strange from other ties as we proved above.`,
    },
    'yad-ephraim': {
      '1#_': `If it was damaged. See Noda BiYehudah Mahadura Tinyana siman 72: wine a Jew deposited with a gentile sealed with two seals as required by law; but then it was fermentation time and because of the strength of the boiling that fermented greatly the force of boiling pushed the body outward and the seal was damaged; and the gentile went and informed the Jew to come and repair his wine — one may be lenient b'di'eved, since he deposited in his house and it was in his hand to inform, and presumably he immediately came to inform and does not delay to remove himself from suspicion — see there regarding an incident where the Jew was with wine on the road and the Jew was not with him; and when he came with the wine the Jew said the seal was damaged on the road when the wagon fell — one must forbid, since even though he sees it was damaged he has no way to inform him and afterwards it remained open in his hand — therefore forbidden — see there. And see in responsum Pnei Moshe part 2 siman 76: just as this question the questioner asked — the seal was damaged because of fermentation — was asked before him and he ruled to forbid, since Israel relied on two seals and the wine in a gentile's cellar — he does not tremble at all; and even though in Beit Yosef siman 58 he wrote that even where there is concern he drank through the tube one may permit where there are other sides for permit — but in our case there is no side of permit, etc. — see there; and it appears from his words that even b'di'eved his intent is to be stringent.`,
      '2#_': `In the hand of Israel — the key and seal. Avodat HaTalmid and Teshuvot HaTashbetz part 3 siman 89: a gentile purifies his wine through Israel and leaves it with a gentile in his courtyard; and at night the guard closes with key and seal — in the keys in those lands that can easily be forged, two seals are required — see there. And in responsum Mahari Katzabi siman 7: an apostate who made his wine in purity and closed it in a storehouse through his Jewish wife on condition he not enter there — only his wife; and the apostate lives with his wife in Israel's courtyard renting a house atop the storehouse; and the key is in the landlord's hand only when he needs to sell wine the wife takes the key and closes and returns the key; and he wrote: even according to the stringent who hold regarding went out and sailed that key and seal are required — nevertheless since he stipulated he not enter and his wife guards it and also the Jew lives there and the key is in the Jew's hand and he troubled to tread in purity and to spend expenses; and also he is apostate to Ishmaelites and he himself is a decree; and even one who is stringent regarding a suspect is more than a gentile — that is regarding depositing; but lest he touched — in such a case, since it is in Israel's possession and locked — even though generally a key is not considered like a seal, here one can say it is permitted and pure — see there.`,
      '3#_': `Standing beside. Avodat HaTalmid and Noda BiYehudah Mahadura Tinyana siman 73: one who rented a cellar from a Jew and the Jew also has his wine in that cellar; and Israel sealed his wine with his seal; and once Israel lacked several measures of wine from one barrel; and from then the Jew took the key in his hand, etc.; and once Israel forgot to seal some barrels and came to the cellar and found the Jew standing beside the unsealed barrels; and found the barrels lacking; and asked him how he came without a key; and he showed he has another key he had last year and lost and now found; and he ruled to forbid the open barrels — for they are lacking before you and presumably he took from them; and even if he took through an unbent nursing woman there are sides of permit for what remains in the barrels — nevertheless one should concern for a bent nursing woman in a place where it is common; and also concern he took much and filled with his inferior wine; and even b'di'eved in such a case one does not permit — see there.`,
    },
  },
};

function writeModule(siman, slug, translations) {
  const n = String(siman).padStart(3, '0');
  const count = Object.keys(translations).length;
  const rel = `siman_${n}/${slug}/part-001.txt`;
  const body = `/** Editorial translations — siman ${siman} / ${slug} (${count} blocks) */
export const TRANSLATIONS = {
${Object.entries(translations).map(([k, v]) => `  '${k}': \`${v.replace(/\\/g, '\\\\').replace(/`/g, '\\`')}\`,`).join('\n')}
};

export const FILES = [['${rel}', '${slug}']];
`;
  const fp = path.join(WORK, `_tr-${siman}-${slug}.mjs`);
  fs.writeFileSync(fp, body, 'utf8');
  return `_tr-${siman}-${slug}.mjs`;
}

function writePatch(siman, modules) {
  const n = String(siman).padStart(3, '0');
  const body = `#!/usr/bin/env node
/** Apply editorial translation modules for siman ${siman} */
import fs from 'fs';
import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

const modules = process.argv.slice(2).length ? process.argv.slice(2) : ${JSON.stringify(modules)};

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\\s*slug: (.+)$/m);
    const seifM = block.match(/^\\s*seif: (.+)$/m);
    const markerM = block.match(/^\\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : '_';
    const key = \`\${seif}#\${marker}\`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(\`ENGLISH/END missing: \${rel} \${key}\`);
    applied.add(key);
    return BLOCK + block.slice(0, enStart + ENG.length + 1) + T[key] + '\\n' + END + block.slice(enEnd + END.length);
  });
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(\`OK \${rel} (\${applied.size} blocks)\`);
  return applied.size;
}

let total = 0;
for (const modName of modules) {
  const modPath = path.join(path.dirname(fileURLToPath(import.meta.url)), modName);
  const mod = await import(pathToFileURL(modPath).href);
  for (const [rel, slug] of mod.FILES) {
    total += patchFile(rel, slug, mod.TRANSLATIONS);
  }
}
console.log(\`[DONE] \${total} blocks\`);
`;
  const fp = path.join(WORK, `_patch-siman-${siman}-editorial.mjs`);
  fs.writeFileSync(fp, body, 'utf8');
}

for (const siman of [129, 130]) {
  const mods = [];
  for (const [slug, tr] of Object.entries(DATA[siman])) {
    mods.push(writeModule(siman, slug, tr));
  }
  writePatch(siman, mods);
  const total = Object.values(DATA[siman]).reduce((a, o) => a + Object.keys(o).length, 0);
  console.log(`siman_${siman}: ${mods.length} modules, ${total} blocks`);
}
